package com.tarapickle.identity.application;
import com.tarapickle.identity.api.IdentityDtos.*; import com.tarapickle.identity.domain.model.*; import com.tarapickle.identity.domain.repository.*; import com.tarapickle.identity.infrastructure.security.JwtTokenService; import lombok.RequiredArgsConstructor; import org.springframework.context.ApplicationEventPublisher; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor public class AuthenticationService { private final UserRepository users; private final CredentialRepository credentials; private final SessionRepository sessions; private final VerificationTokenRepository verificationTokens; private final ResetTokenRepository resetTokens; private final RoleRepository roles; private final UserRoleRepository userRoles; private final ConsentRepository consents; private final SecurityEventRepository events; private final PasswordEncoder passwords; private final JwtTokenService tokens; private final ApplicationEventPublisher publisher; private final Clock clock;
 private static String email(String e){return e.strip().toLowerCase(Locale.ROOT);} private void policy(String p){if(p.length()<12||p.length()>128||!p.matches(".*[A-Z].*")||!p.matches(".*[a-z].*")||!p.matches(".*[0-9].*"))throw new IdentityException(HttpStatus.UNPROCESSABLE_ENTITY,"WEAK_PASSWORD","Password must be 12-128 characters and include upper-case, lower-case, and numeric characters.");}
 @Transactional public RegistrationResponse register(RegisterRequest r,String ip){policy(r.password());String mail=email(r.email());if(users.existsByEmailIgnoreCase(mail))throw new IdentityException(HttpStatus.CONFLICT,"EMAIL_ALREADY_REGISTERED","An account with this email already exists.");Instant now=clock.instant();User u=users.save(new User(UUID.randomUUID(),mail,r.givenName().strip(),r.familyName().strip(),now));credentials.save(new UserCredential(u.getId(),passwords.encode(r.password()),now));Role player=roles.findByCode("PLAYER").orElseThrow();userRoles.assign(u.getId(),player.getId());consents.saveAll(List.of(new ConsentRecord(u.getId(),"TERMS_OF_SERVICE","2026-08-21",now),new ConsentRecord(u.getId(),"PRIVACY_POLICY","2026-08-21",now)));String raw=tokens.opaque();verificationTokens.save(new VerificationToken(u.getId(),JwtTokenService.hash(raw),now,now.plus(Duration.ofHours(24))));events.save(new SecurityEvent(u.getId(),null,"REGISTRATION","SUCCESS",now,ip));publisher.publishEvent(new EmailRequested(EmailRequested.Kind.VERIFICATION,mail,raw));return new RegistrationResponse(u.getId(),mail,u.getStatus().name());}
 @Transactional public void verify(String raw,String ip){Instant now=clock.instant();VerificationToken t=verificationTokens.findByTokenHash(JwtTokenService.hash(raw)).orElseThrow(()->new IdentityException(HttpStatus.UNPROCESSABLE_ENTITY,"INVALID_VERIFICATION_TOKEN","Verification token is invalid or expired."));if(!t.valid(now))throw new IdentityException(HttpStatus.UNPROCESSABLE_ENTITY,"INVALID_VERIFICATION_TOKEN","Verification token is invalid or expired.");User u=users.findById(t.getUserId()).orElseThrow();t.use(now);u.verifyEmail(now);events.save(new SecurityEvent(u.getId(),null,"EMAIL_VERIFIED","SUCCESS",now,ip));}
 @Transactional public void resend(String supplied){users.findByEmailIgnoreCase(email(supplied)).filter(u->u.getStatus()==AccountStatus.PENDING_VERIFICATION).ifPresent(u->{Instant now=clock.instant();verificationTokens.findAllByUserId(u.getId()).forEach(t->{if(t.valid(now))t.use(now);});String raw=tokens.opaque();verificationTokens.save(new VerificationToken(u.getId(),JwtTokenService.hash(raw),now,now.plus(Duration.ofHours(24))));publisher.publishEvent(new EmailRequested(EmailRequested.Kind.VERIFICATION,u.getEmail(),raw));});}
 @Transactional public TokenResponse login(LoginRequest r,String agent,String ip){Instant now=clock.instant();Optional<User> found=users.findByEmailIgnoreCase(email(r.email()));if(found.isEmpty()){events.save(new SecurityEvent(null,null,"LOGIN","FAILED",now,ip));throw IdentityException.badCredentials();}User u=found.get();UserCredential c=credentials.findById(u.getId()).orElseThrow();if(!passwords.matches(r.password(),c.getPasswordHash())){events.save(new SecurityEvent(u.getId(),null,"LOGIN","FAILED",now,ip));throw IdentityException.badCredentials();}if(u.getStatus()!=AccountStatus.ACTIVE)throw new IdentityException(HttpStatus.FORBIDDEN,"ACCOUNT_NOT_ACTIVE","Account is not active.");String refresh=tokens.opaque();UserSession s=sessions.save(new UserSession(UUID.randomUUID(),u.getId(),JwtTokenService.hash(refresh),now,tokens.refreshExpiry(now),agent,ip));events.save(new SecurityEvent(u.getId(),s.getId(),"LOGIN","SUCCESS",now,ip));return issue(u,s,refresh,now);}
 @Transactional public TokenResponse refresh(String raw){Instant now=clock.instant();String hash=JwtTokenService.hash(raw);Optional<UserSession> reused=sessions.findByPreviousTokenHash(hash);if(reused.isPresent()){UserSession compromised=reused.get();compromised.revoke(now);events.save(new SecurityEvent(compromised.getUserId(),compromised.getId(),"REFRESH_TOKEN_REUSE","FAILED",now,null));throw IdentityException.badCredentials();}UserSession s=sessions.findByRefreshTokenHash(hash).orElseThrow(IdentityException::badCredentials);if(!s.active(now))throw IdentityException.badCredentials();User u=users.findById(s.getUserId()).orElseThrow();if(u.getStatus()!=AccountStatus.ACTIVE)throw IdentityException.badCredentials();String next=tokens.opaque();s.rotate(JwtTokenService.hash(next),now);return issue(u,s,next,now);}
 @Transactional public void forgot(String supplied){users.findByEmailIgnoreCase(email(supplied)).ifPresent(u->{Instant now=clock.instant();String raw=tokens.opaque();resetTokens.save(new PasswordResetToken(u.getId(),JwtTokenService.hash(raw),now,now.plus(Duration.ofHours(1))));publisher.publishEvent(new EmailRequested(EmailRequested.Kind.RESET,u.getEmail(),raw));events.save(new SecurityEvent(u.getId(),null,"PASSWORD_RESET_REQUESTED","SUCCESS",now,null));});}
 @Transactional public void reset(ResetRequest r){policy(r.newPassword());Instant now=clock.instant();PasswordResetToken t=resetTokens.findByTokenHash(JwtTokenService.hash(r.token())).orElseThrow(()->new IdentityException(HttpStatus.UNPROCESSABLE_ENTITY,"INVALID_RESET_TOKEN","Reset token is invalid or expired."));if(!t.valid(now))throw new IdentityException(HttpStatus.UNPROCESSABLE_ENTITY,"INVALID_RESET_TOKEN","Reset token is invalid or expired.");t.use(now);credentials.findById(t.getUserId()).orElseThrow().changePassword(passwords.encode(r.newPassword()),now);sessions.findAllByUserIdOrderByCreatedAtDesc(t.getUserId()).forEach(s->s.revoke(now));events.save(new SecurityEvent(t.getUserId(),null,"PASSWORD_RESET","SUCCESS",now,null));}
 private TokenResponse issue(User u,UserSession s,String refresh,Instant now){return new TokenResponse(tokens.access(u.getId(),s.getId(),userRoles.roles(u.getId()),now),refresh,"Bearer",tokens.accessSeconds());}
}
